def patch(path):
    src = open(path, encoding="utf-8").read()
    anchor_c = '    "注意机制": ["注意机制", "选择性注意", "分散注意", "什么是注意机制"],'
    new_c = '''    "儿童用药": ["抗生素", "乱吃", "孩子病了", "不吃药", "扛着", "喂药",
              "灌下去", "科学用药", "用药"],
    "医养结合": ["养老院一床难求", "养老院能看病", "养老院管养老",
              "医养结合", "养老医疗", "送养老院", "一床难求"],
    "付费自习室": ["付费自习室", "自习室", "自习", "在家学不进去",
              "高效自习", "自习还要花钱"],
    "教师收礼": ["给老师送礼", "老师收礼", "送礼是感谢", "感谢老师",
              "收点礼", "教师收礼", "收礼"],
    "银行网点消失": ["银行网点", "网点", "银行都在手机上", "网点少",
              "银行也要赚钱", "老人办事", "办业务"],
    "大学生生活费": ["生活费", "一个月生活费", "生活费不够", "要多少给多少",
              "生活费怎么给", "管自己的生活费"],
    "宠物训练": ["宠物不听话", "宠物训练", "训练残忍", "不训练",
              "宠物伤人", "怎么训练", "行为问题"],
    "学生睡眠": ["缺觉", "作业多", "睡得少", "熬夜是努力", "睡眠",
              "睡够", "作业和睡眠", "睡眠不足"],'''
    assert anchor_c in src, "cluster anchor missing"
    src = src.replace(anchor_c, new_c + "\n    " + anchor_c, 1)

    anchor_d = '    "注意机制": "注意机制是认知资源的选择性分配——选择性注意（聚焦）/分散注意（多任务）/持续注意；对应CSPMN只匹配激活条件空间",'
    new_d = '''    "儿童用药": "孩子老生病、抗生素为什么不能乱吃，是『家长的心急』vs『用药的科学』的矛盾——孩子生病（发烧/咳嗽/感冒），家长急（想快点好），医生的药见效慢（病毒感冒要一周），家长就自己加药/换药/喂抗生素（觉得消炎=抗生素），结果抗生素滥用（耐药性：以后真感染了药没效）——『心急』和『科学』在孩子的药盒里打架。真相：①为什么孩子老生病——正常现象：孩子免疫系统在发育（每年感冒6-8次是正常的（幼儿园交叉感染更多）），『老生病』不等于体弱（是免疫系统在练兵），判断标准：发烧频率/恢复速度/生长发育（都在正常范围就没事，频繁到影响发育才就医）——别用『老生病』吓自己（也吓孩子）；②抗生素为什么不能乱吃——抗生素只杀细菌（对病毒无效）：孩子生病大多是病毒（感冒/流感/幼儿急疹，抗生素没用），乱吃抗生素的代价：耐药性（细菌进化出抗药性，以后真细菌感染无药可用——超级细菌就是这么来的）、副作用（伤肠道菌群（腹泻/过敏）、肝肾负担）——原则：医生确诊细菌感染（血常规白细胞高/扁桃体化脓）才用抗生素，家长不主动要求不自己加；③孩子病了不吃药扛着行吗——看情况：扛（病毒感冒（无并发症）：多喝水多休息，靠免疫力，一周自愈——扛得住）、不扛（发烧超过38.5（吃退烧药缓解不适）/细菌感染（不用药会加重：中耳炎/肺炎）/精神状态差（嗜睡/萎靡——立即就医））——『扛』的是普通病毒，『不扛』的是细菌/高烧/异常状态，区分标准：状态（能玩能吃=观察，蔫了=就医）；④喂药难灌下去不行吗——灌药危险：呛咳（药进气管=窒息/吸入性肺炎，灌药是事故高发原因）、恐惧（强行灌药让孩子更怕吃药，下次更难喂）——喂药技巧：工具（喂药器/滴管/针管式喂药器，比勺子精准）、姿势（半坐，别仰头灌）、方法（混少量果泥/藏在酸奶里（先问医生是否可混）、奖励（吃完药给个拥抱/小奖励）、氛围（别吓唬『不吃药打针』——把吃药讲成勇敢的事）。怎么科学用药：①遵医嘱——药量（按体重算，别按年龄估（药量错了=白吃或中毒））、疗程（医生说吃几天吃几天（抗生素不能见好就收，疗程不足=耐药））、间隔（一天三次=每8小时一次，别按三餐）；②退烧药——38.5以上再用（对乙酰氨基酚/布洛芬二选一，别混吃（过量伤肝））、物理降温辅助（温水擦/少穿）；③观察信号——立即就医：高烧不退（3天+）/抽搐/呼吸困难/精神极差/皮疹/呕吐腹泻脱水——别硬扛；④心态——孩子生病是常态（一年几次正常），科学用药（遵医嘱+不乱加药）比『快点好』重要（急病乱投医才是最大的风险）。核心：儿童用药的关键是『别急』——病毒自愈、细菌听医嘱、抗生素不乱吃、喂药不硬灌，家长稳住，孩子才安全",
    "医养结合": "养老院一床难求、养老院能看病吗，是『养老的需求』vs『医疗的配套』的矛盾——老人老了（生活自理难+慢性病多：高血压/糖尿病/心脑血管），养老需要『养+医』一体（光管吃住不行，病了要有医），但传统养老院只管养老（病了送医院，来回折腾）、医院只管治病（病好了没处养，压床不出院），『医养分离』让老人两头奔波，『医养结合』（养老院里有医疗/医院里有养老）是方向但推进难（钱/人才/政策）。真相：①为什么养老院一床难求——供需失衡：老龄化加速（60岁以上人口超3亿，还在增）、养老院床位不足（公办养老院排队几年（一床难求），民营的贵/质量参差）、老人观念转变（独居/子女忙，养老院成为选择）——『一床难求』是老龄化+供给不足的必然（公办挤破头，民办住不起）；②养老院能看病吗——传统不能（养老院只管生活照料（吃住/护理），看病要家属送医院）、医养结合的能（内设医务室/护理院/签约医院（常见病在院里看，急症绿色通道转院））——判断养老院：看有没有医疗配套（内设医疗/合作医院/医生定期巡诊），这是养老院质量的核心分水岭（有医的养老院，老人少受折腾）；③养老院管养老就行看病去医院——分开的现实问题：老人去医院的折腾（接送/排队/陪护，家属请假）、慢病管理断档（出院后没人管（药停了/指标没人测），又复发再住院——『医养分离』的循环）、压床（病好了赖在医院（回家没人照顾），占用医院床位——医养分离浪费两头资源）；④医养结合钱谁出——现实难题：医养结合成本高（医疗设备+医护团队+场地，比纯养老贵）、支付（医保覆盖有限（养老部分不报，医疗部分报），自费部分是多数家庭的压力）、政策补贴（政府推医养结合试点/养老机构医疗纳入医保定点，但覆盖还不足）——『钱谁出』是医养结合最大的坎（老人/家庭/医保/政府四方分担，机制还在建）。怎么做：①养老机构——选有医疗的（内设医务室/护理型床位/签约医院）、护理等级（自理/半护/全护：评估老人需求，别一刀切）、实地考察（看医疗设备/问医护配比（多少老人一个护士））；②政策层面——医养结合推广（养老机构内设医疗/医院办养老/社区医养驿站）、医保衔接（养老机构医疗纳入医保、长期护理保险试点（失能老人护理费用报销））；③家庭层面——尽早规划（老人失能前考察好养老院/医养机构，别等病倒才找）、子女分工（老人医疗有专人对接）、钱（养老+医疗双储备（养老金+商业护理险））；④观念——养老院的『医』是刚需（老人病多，有医的养老院才是真养老）、医养结合是趋势（老龄化倒逼，会越来越普及）——老人养老，医是底线。核心：医养结合是养老的刚需升级——养老院没医=老人来回折腾，医养分离是两头浪费，政策推+机构建+家庭选，让老人『养有处、病有医』",
    "付费自习室": "付费自习室这么火、在家学不进去，是『学习的环境』vs『免费的诱惑』的矛盾——付费自习室（20-60元/天，沉浸式座位/独立隔间/安静氛围）火了（考研/考公/备考党聚集），因为『在家学不进去』（床/手机/家人，诱惑太多）——花钱买的是『环境』（离开家的物理隔离+花钱的自我承诺），『免费』的图书馆和『付费』的自习室，差的不是钱是『氛围』。真相：①为什么付费自习室这么火——需求真实：在家学不进去（床/手机/冰箱/家人——诱惑太多，自制力是有限资源）、图书馆不够用（座位少/闭馆早/占座严重）、付费自习室解决痛点（固定座位/安静/沉浸氛围/营业到很晚（很多24小时））——火的原因是『它精准解决了备考党的环境需求』（花钱买专注）；②在家学不进去去自习室有用吗——有用但有前提：有用（物理隔离（离开家=离开诱惑）+花钱承诺（花了钱不学=亏，心理压力变成动力）+同伴效应（周围人都在学，你不学格格不入））、前提（你自己想学（自习室不生产动力，只放大动力：不想学的人在哪都学不进去，自习室只是放大器））——去自习室是『借环境』，借完要还（你最终要能在任何环境学）；③自习还要花钱值吗——算账：值（20-60元/天 vs 备考时间（一天10小时高效学习，每小时2-6元——比咖啡厅便宜比图书馆自由，而且学习效率翻倍））、不值（自制力强（在家/图书馆就能学，花钱是浪费））——值不值看你的自制力：在家能学=不用花，在家学不进去=花的值（时间比钱贵，一天白混=损失一天）；④免费图书馆不够用吗——够但不够好：图书馆免费（省钱）、座位有限（旺季抢座）、环境限制（不能带吃的/不能讨论/闭馆早）、距离（离家远）——付费自习室补的是图书馆的短板（座位保障/营业时间/学习氛围），两者互补不冲突：能抢到图书馆座位就用免费的，抢不到/需要晚自习就付费。怎么选：①先评估自己——在家能学吗（能：省钱了；不能：自习室/图书馆）、自制力差选付费（花钱逼自己）、自制力还行选图书馆（省钱）；②选自习室——看环境（安静/座位舒适/光线/通风）、看价格（次卡/月卡（备考党月卡划算，先试一天）、看配套（储物柜/茶水/打印/休息区）、看位置（离家近/地铁方便，太远坚持不下来）；③自习室使用——固定座位（每天同一位置，形成仪式感）、手机隔离（手机放储物柜/关机，自习室最大的敌人）、时段（固定时段去（9-18点），形成生物钟）；④心态——自习室是工具不是依赖（『没去自习室就不学』是借口：在家/图书馆也能学）、花钱买了环境就要值回票价（去一次学一天，别去自习室刷手机）——高效自习的公式：环境（自习室/图书馆）+工具（手机隔离）+习惯（固定时段），三者齐了在哪都能学。核心：付费自习室买的是环境不是动力——自制力弱就借环境（花钱买专注，值），自制力强就省这钱（图书馆+在家一样学），别让『没有自习室』成为不学习的借口",
    "教师收礼": "家长给老师送礼、老师收礼是常态吗，是『家长的焦虑』vs『教育的公平』的矛盾——家长送礼（想让老师多关照孩子：座位/提问/表扬，『礼多人不怪』的焦虑）、老师收礼（觉得是尊重/盛情难却/潜规则），但收礼的代价：教育公平受损（收礼的老师对送礼的孩子另眼相看，没送礼的孩子被忽视）、师德崩塌（教师被金钱绑架，教育变交易）——『送礼』是家长用钱买安心，『收礼』是老师用公平换利益。真相：①为什么家长要给老师送礼——三重焦虑：关照需求（希望老师多关注孩子：调座位/多提问/给机会，家长觉得不送礼老师不上心）、从众压力（别的家长都送，我不送孩子会不会被差别对待）、感恩表达（老师确实辛苦，家长想表达感谢，送礼是最直接的方式）——送礼的根源是『信息不对称』（家长不知道老师会不会偏心，只能送礼买个安心）；②老师收礼是常态吗——是潜规则不是常态：多数老师不收（师德要求（教师法/师德规范明确禁止收礼）+风险（被举报/处分））、部分老师收（小恩小惠（教师节鲜花/贺卡——人情往来）、贵重礼（红包/购物卡——违规））——『收礼』分两类：表达心意（几块钱的贺卡/鲜花，老师收是人之常情，不算违规）vs 利益输送（贵重礼/红包，违规甚至违法（受贿））——『常态』是焦虑的放大（一个收礼的老师被传成普遍，多数好老师被冤枉）；③送礼是感谢老师有错吗——感谢没错（老师辛苦，感恩是美德），错的是『用礼金表达感谢』（感谢可以（贺卡/鲜花/当面道谢/配合学校工作），礼金不行（钱=交易，老师收了就欠人情，公平就没了））——家长的正确姿势：感谢走心不走钱（孩子亲手做的贺卡/一句真诚的谢谢/配合老师的工作，比红包更有价值）；④老师辛苦收点礼怎么了——辛苦和收礼是两回事：辛苦（老师值得尊重/感谢——用尊重和配合回报）、收礼（收礼是职业红线（违反师德规范，严重的违法）——『辛苦』不是收礼的理由（医生辛苦能收红包吗？法官辛苦能收礼吗？——职业有职业的规矩））——真正尊重老师的方式：不让他为难（别用送礼考验他的师德）。怎么感谢不送礼：①感谢的正确方式——贺卡/鲜花（孩子手写贺卡/家长送花，教师节的心意）、配合（及时回复老师/配合学校工作，老师最需要的是家长配合）、口碑（孩子说『老师教得好』，家长在家长群里真诚表扬——口碑是最好的感谢）；②管理自己——不送礼（家长不送，老师就没得收：从自己做起，别用送礼污染孩子眼中的师生关系）、不焦虑（老师不会因为你不送礼就亏待孩子（好老师一视同仁，收礼的老师早晚出事）——用孩子的表现（进步/快乐）衡量老师，不用礼金衡量）；③发现收礼——老师收贵重礼：委婉拒绝送礼（『孩子进步就是最大的感谢』）、举报（教师收礼可向学校/教育局举报（有规定有渠道））、换老师（严重情况（暗示送礼/差别对待）——这不是你的孩子的问题，是这个老师的问题）；④观念——教育公平是底线（老师收礼=教育变交易，最受伤的是没送礼的孩子和教育的公信力）、师生关系本该纯粹（老师教书育人，家长配合支持，孩子努力学习——三角关系不需要钱来润滑）。核心：教师收礼是教育公平的腐蚀剂——家长别用送礼买安心（配合和感谢比红包好），老师别用收礼换利益（师德是职业的底线），让师生关系回到教书育人的纯粹",
    "银行网点消失": "银行网点越来越少、老人怎么办，是『银行的效率』vs『老人的便利』的矛盾——银行转型线上（手机银行/APP/数字支付，网点运营成本高（租金/人工/安全设施），关网点降成本是趋势）、老人不适应（不会用手机银行/看不清屏幕/怕被骗，习惯柜台办业务（存折/现金/当面办））——『网点消失』让老人被数字化抛弃（最近的网点越来越远，柜台越来越少（很多网点取消人工柜台改自助机））。真相：①为什么银行网点越来越少——成本压力（网点运营贵（租金+人工+安保，一个网点一年几百万）、线上替代（手机银行办95%的业务，网点业务量暴跌（一天没几个客户））、银行转型（关网点降成本（财报压力），把资源投向线上）——关网点是银行的理性选择（商业逻辑），但代价由最依赖网点的老人承担；②银行都在手机上网点有必要吗——对年轻人没必要（手机银行/扫码/转账，一年不去一次网点），对老人有必要（不会用/不敢用/存折现金业务必须柜台）——『网点有没有必要』取决于谁用：银行只算自己的账（线上省钱），忘了老人的账（网点是老人唯一的金融入口）——金融服务的普惠性（让所有人能获得服务）要求网点不能一关了之；③网点少老人怎么办——现实困境：老人去网点（越来越远（最近的网点关到几公里外）/排队（柜台少，办一次业务半天））、不会用手机（子女不在身边/没人教/不敢点（怕被骗））、被骗风险（不会用手机+网点远→老人找陌生人帮忙（『代办』陷阱））——网点消失让老人『办事难+更易被骗』双输；④银行也要赚钱网点关了就关了——商业逻辑没错（银行是企业要盈利），但『关网点』不是唯一答案（可以转型不关闭：网点小型化（社区支行/自助+人工混合）、服务差异化（保留柜台服务老人/预约上门服务）、线上适老化（大字版/语音/人工客服）——『赚钱』和『服务老人』不冲突（服务好老人是银行的客户价值：老人存款是大头（中国居民存款一半在老年人手里））——一刀切关网点是懒政式降本。怎么办：①银行——网点转型不消失（社区支行/自助+人工）、适老服务（大字版APP/语音操作/电话银行人工服务/预约上门（行动不便老人））、保留现金业务（拒收现金违法，柜台保留现金存取）；②老人——学用手机（子女耐心教（大字模式/转账演示，一次一个功能）、存折业务柜台（保留存折账户，柜台总能办））、安全（不点陌生链接/不透露密码/大额转账先问子女——老人被骗的最大漏洞是没人把关）；③子女——代办（网上业务子女代办（转账/缴费），老人现金需求陪去柜台）、教防骗（跟老人说：银行不会打电话要验证码/让转账）、关注（老人金融需求（养老金到账/存单到期）子女留意）；④制度——监管要求（银行网点撤销要报批/金融监管局评估（周边老人服务覆盖）、基本金融服务兜底（偏远地区保留基础网点/流动服务车））——金融普惠是底线，不能只算商业账。核心：银行网点消失是效率与公平的博弈——线上化省了银行的成本，不能省了老人的权利，转型（小型化/适老化）+兜底（监管/保留现金服务），让老人和年轻人一样能办业务",
    "大学生生活费": "大学生一个月生活费多少合适、生活费不够怎么办，是『孩子的消费』vs『家庭的预算』的矛盾——大学生生活费（吃饭+日用品+社交+学习，一线1500-2500/二三线1000-1500是常见区间）没有标准答案（看城市/家庭/消费观），矛盾在：孩子觉得不够（同学都这样花/物价涨了/要社交）、家长觉得太多（自己一个月工资才几千/怕孩子乱花）——『多少合适』是家庭经济和孩子消费观的磨合。真相：①大学生一个月生活费多少合适——参考公式：吃饭（食堂一天30-40=900-1200）+日用品/话费（200-300）+学习（书/资料100-200）+社交/娱乐（300-500）≈1500-2500（一线）/1000-1800（二三线）——『合适』= 覆盖基本生活+适度社交，家庭经济决定上限（富裕多给，普通给够基本——别用生活费攀比）；②生活费不够怎么办——先找原因：不会花（月初大手大脚月底吃土→记账/预算管理）vs 真的不够（物价/社交需求真实高于给的数→沟通加钱/自己赚）——解决路径：预算（生活费到手先分（吃饭/日用/存/社交，按比例））、开源（兼职（家教/校内岗/技能变现——生活费不够不是只能省，还能赚））、节流（食堂为主（外卖是生活费杀手）、团购/优惠（学生优惠/拼单））；③多给生活费是惯孩子吗——看怎么给：惯（无上限（要多少给多少，不教管理——孩子学不会理财，越大越能花））、教育（有规则地给（固定数额+教记账+超额自理（花完就没了，自己想办法））——给生活费是理财教育（孩子第一次管理一笔钱，教他预算/记账/取舍，比给多少重要）；④孩子要多少给多少行吗——不行：无原则满足（孩子学不会『钱是有限的』（想要就给=永远不够：生活费给了要买手机，买了手机要电脑——欲望没有底））——应对：定规则（生活费固定（按学期/按月），大项支出（手机/电脑）另算（家庭协商/自己攒）、沟通（孩子要钱时问清用途（合理（学习/必要社交）支持，不合理（攀比消费）拒绝+解释））——给钱的原则：满足需要，不满足欲望（需要（吃穿学）满足，欲望（攀比/超前）引导）。怎么给才合理：①定标准——按城市/家庭（一线2000左右/二三线1500左右，家庭收入10%以内合理）、先协商（开学前和孩子谈：这个数够吗？哪些算生活费哪些另算——孩子参与定价才有责任感）；②按月给——按月/按学期给（培养长期规划），不按天给（天天要=没学会规划）、花完不补（紧急情况（生病/意外）除外，日常花完=自己扛（下个月吸取教训））；③教管理——记账（生活费APP/本子，月底复盘）、三账户（生活费/应急/储蓄，培养储蓄习惯）、消费观（想要和需要（攀比消费识别）——生活费是理财第一课，教好了受用一生）；④心态——生活费是教育投入不是施舍（孩子花的是家庭的信任，合理给+教管理=双赢）、别用生活费控制孩子（『给钱就是大爷』的家长，孩子会逆反）——生活费给的合理，孩子学会独立，家庭关系也健康。核心：大学生生活费的标准是『够基本+可商量』——按家庭定数、按月发放、教记账管理、超额自己想办法，生活费是孩子经济独立的起点，不是攀比的筹码",
    "宠物训练": "宠物不听话、训练是打骂吗，是『宠物行为』vs『管教方式』的矛盾——宠物（狗/猫）有天性（狗爱叫/拆家/扑人，猫抓沙发/半夜跑酷），『不听话』是宠物的天性撞上人类的规矩，训练（让宠物学会规则：定点排便/不咬人/听指令）是养宠的必修课——但训练方式分歧：打骂（见效快但伤关系）vs 科学训练（正向激励，慢但健康）——『管教』的边界在哪。真相：①为什么宠物不听话——不是宠物笨，是没训练/训练错：宠物不懂人话（它听不懂『别叫了』，只懂条件反射：叫了有回应=继续叫）、行为是需求的表达（拆家=无聊/分离焦虑、乱叫=警惕/求关注、抓沙发=磨爪子（天性））——『不听话』是宠物用它的方式在表达，管教前先读懂它要什么；②宠物训练是打骂吗——不是：打骂是错误训练（打骂的后果：恐惧（宠物怕你（不是服从你），关系破裂）、攻击（被逼急了咬人——打骂是宠物攻击行为的第一诱因）、无效（打的时候怕，不打就犯——它没学会『该做什么』，只学会『别被抓到』））——科学训练（正向激励：做对了奖励（零食/表扬），做错了忽略/引导——宠物学的是『做什么有奖励』，主动做对）；③宠物就该自由训练残忍吗——『自由』和『规则』不冲突：自由（宠物需要活动/陪伴/天性释放（遛狗/玩耍/磨爪））vs 规则（安全规则（不咬人/不扑人/过马路牵绳）——规则保护宠物也保护别人）——训练不是剥夺自由（是教它在自由和安全之间平衡：训练过的狗能自由奔跑（唤回可靠），没训练的不敢松绳），残忍的是放任（不训练=宠物伤人被处置/被遗弃，那才残忍）；④不训练宠物伤人谁负责——主人负责：法律（民法典：动物致害，饲养人/管理人担责（咬伤赔医疗费+精神损失））、情理（你的宠物你负责（管不住就拴住——不训练+不拴绳=把风险推给别人））——『不训练』不是宠物的自由，是主人的失职（伤人赔偿/宠物被处置/邻居投诉——最后受伤的是宠物）。怎么训练不伤害：①正向激励——奖励正确（坐下→零食，定点排便→奖励，做对立刻奖励（3秒内，宠物才建立关联））、忽略错误（乱叫时不理（叫没回应=没意义，安静了再理）、引导替代（拆家→给磨牙玩具，抓沙发→给猫抓板——用对的行为替代错的行为）；②基础课——定点排便（幼宠黄金期（3-6个月最好教））、坐下/等待/唤回（安全三宝（防止扑人/乱跑/危险））、社会化（多接触人/狗/环境（幼年社会化减少成年攻击/恐惧））；③耐心与一致——训练靠重复（一天5-10分钟，坚持几周）、全家一致（规则统一（妈妈说不许上沙发，爸爸说上来——宠物会混乱）、不放弃（宠物学习有个体差异（有的聪明有的慢），别因为教不会就骂）；④专业求助——行为问题严重（咬人/分离焦虑/护食）：找宠物行为训练师（专业评估+方案），别自己瞎打骂——打骂是最后的手段，而且基本不是手段（专业训练师不用打骂也能解决大部分行为问题）。核心：宠物训练是爱的教育不是暴力的征服——正向激励让宠物主动做对，打骂只会换来恐惧和攻击，训练好的宠物是快乐的家庭成员，不训练的是隐患（伤人/被弃），你怎么对它，它怎么对世界",
    "学生睡眠": "学生都缺觉、作业多到做不完，是『学业的任务』vs『身体的底线』的矛盾——中小学生睡眠不足是普遍问题（教育部规定：小学生10小时/初中生9小时/高中生8小时，实际普遍少1-3小时），原因：作业多（应试导向，作业量超负荷）+课外班（兴趣班/补习班挤压）+拖延/手机（睡前刷手机）——『缺觉』的代价（记忆力下降/注意力差/情绪暴躁/生长激素分泌不足（影响身高）），作业和睡眠抢时间，身体在买单。真相：①为什么学生都缺觉——三重挤压：作业（应试教育下作业量大（尤其初高中，写到11点是常态））、课外班（放学后补习/兴趣班，回家再写作业——时间被双重占用）、习惯（睡前玩手机（短视频/游戏，越刷越清醒，入睡推迟））——缺觉是『学业负担+时间管理+电子设备』的合力，不是孩子不想睡（是真的没时间/睡不着）；②作业多到做不完怎么办——先分析：效率问题（磨蹭（写一会玩一会，2小时的作业写4小时）vs 量的问题（真的多（全班都写不完））——应对：效率（作业计时（每科限时，像考试）、先难后易（脑子清醒时啃难题）、排除干扰（写作业时手机放另一个房间））、量（和老师沟通（作业太多/长期写不完，家长反映）、学校层面（减负政策在推，家长可以推动班级减负））；③睡得少学得多有错吗——错：睡眠是学习的一部分（记忆巩固（白天学的知识在睡眠中固化——睡不够=学了记不住）、注意力（缺觉的孩子上课走神，白天低效→晚上补作业→更缺觉——恶性循环）——『睡得少学得多』是错觉（缺觉的学习效率断崖式下跌，睡8小时学6小时 > 睡5小时学10小时）；④熬夜是努力不是问题——不是：熬夜是『用身体换时间』（短期看着努力，长期是透支：免疫力下降（老生病）/情绪问题（暴躁/抑郁倾向）/发育受损（生长激素夜间分泌，缺觉影响身高）——『努力』的正确姿势是『高效』不是『熬夜』（真正努力的人管理时间，不努力的人才熬夜装努力）——熬夜不是勋章是警报（该减负/该改方法了）。怎么平衡：①作业管理——效率优先（计时/专注/先难后易，把作业时间压缩）、学会取舍（太难的题标记问老师（别死磕到半夜）、副科作业合理安排）；②睡眠保障——固定作息（每天同一时间睡（周末也尽量不打破生物钟）、睡前仪式（睡前一小时不碰手机（蓝光抑制褪黑素）、洗澡/阅读/放松——给孩子睡眠的『仪式感』）；③家庭配合——家长别加码（孩子写完作业别再布置额外练习——作业之外的时间是孩子的（睡眠/运动/玩））、营造环境（家里安静/灯光调暗/家长也早睡（孩子睡家长刷手机=诱惑））；④观念——睡眠是底线（作业做不完可以沟通（身体比作业重要）、睡眠不足是健康问题（不是懒惰）、减负从家长做起（别用『为你好』透支孩子的身体）——孩子的睡眠是家长的责任，作业是老师的事，健康是底线。核心：学生睡眠是健康的底线不是努力的敌人——作业要效率（别磨蹭）、睡眠要保障（10小时小学生/9小时初中生）、熬夜不是努力是透支，别让作业和手机偷走孩子的睡眠",
    "注意机制": "注意机制是认知资源的选择性分配——选择性注意（聚焦）/分散注意（多任务）/持续注意；对应CSPMN只匹配激活条件空间",'''
    assert anchor_d in src, "daily anchor missing"
    src = src.replace(anchor_d, new_d, 1)
    open(path, "w", encoding="utf-8").write(src)
    print("patched")

